def is_good(m):
    s_m = str(m)
    # Check distinct nonzero digits
    if len(set(s_m)) != len(s_m) or '0' in s_m:
        return False

    # Base case: single digit
    if len(s_m) == 1:
        return True

    # Recursive case: remove one digit
    for i in range(len(s_m)):
        m_prime_str = s_m[:i] + s_m[i+1:]
        m_prime = int(m_prime_str)
        if m_prime != 0 and m % m_prime == 0 and is_good(m_prime):
            return True

    return False

