        # We need to find numbers of 'length' that have a 'length-1' digit good divisor
        # The 'length-1' digit good divisors are already in good_numbers

        # We iterate through all good numbers of length-1
        good_numbers_of_prev_length = [m for m in good_numbers if len(str(m)) == length - 1]

        for m_prime in good_numbers_of_prev_length:
            s_prime = str(m_prime)
            for digit in "123456789":
                if digit in s_prime:
                    continue
                for i in range(length):
                    # Insert digit at position i
                    m_str = s_prime[:i] + digit + s_prime[i:]
                    m = int(m_str)
                    if m % m_prime == 0:
                        current_length_good.add(m)

        if not current_length_good:
